+//! Integration tests for the diff-based reactive emitter in `pathland-core`.
+
+use std::collections::BTreeMap;
+
+use pathland_core::{
+    category, init_memory, listener, property_id, size, style, tree, value_type, Guest, Host,
+    MemoryLayout, Opcode,
