     let ops: Vec<pathland_core::Opcode> = batch.frame().opcodes().collect();
     assert_eq!(ops.len(), 1, "only the bound node emits");
     assert_eq!(ops[0].command(), style::SET_TEXT);
     assert_eq!(ops[0].a(), 2);
